 * @returns {Map<string, {name: string, command: string, needs: string[], reads: string[], writes: string[]}>} the tasks by name, in declaration order.
 */
export function parse(lines) {
  const tasks = new Map()
  const pending = []

  lines.forEach((raw, index) => {
    const line = index + 1
    const text = raw.trim()
    if (text === '' || text.startsWith('#')) return
    const words = text.split(/\s+/u)
    const directive = words[0]
    const rest = words.slice(1)

    if (directive === 'task') {
      if (rest.length < 2) throw new ParseError(line, 'expected task <name> <word>...')
      const [name, ...command] = rest
      if (!isName(name)) throw new ParseError(line, `invalid task name ${name}`)
      if (tasks.has(name)) throw new ParseError(line, `task ${name} is declared twice`)
      tasks.set(name, { name, command: command.join(' '), needs: [], reads: [], writes: [] })
      return
    }

    const attaching = ATTACHING.get(directive)
    if (attaching === undefined) throw new ParseError(line, `unknown directive ${directive}`)
    if (rest.length < 2) throw new ParseError(line, `expected ${directive} <name> <${attaching.word}>...`)
    const [name, ...items] = rest
    if (attaching.field !== 'needs') {
      for (const item of items) {
        if (!isPath(item)) throw new ParseError(line, `invalid path ${item}`)
      }
    }
    pending.push({ field: attaching.field, name, items })
  })

  for (const { field, name, items } of pending) {
    if (!tasks.has(name)) throw new ParseError(0, `unknown task ${name}`)
    const task = tasks.get(name)
    for (const item of items) {
      if (field === 'needs' && !tasks.has(item)) throw new ParseError(0, `unknown task ${item}`)
      if (!task[field].includes(item)) task[field].push(item)
    }
  }

  return tasks
}
